 "content": "def transform(grid):
    """Compare the two equal-sized panels separated by a solid line."""
    h, w = len(grid), len(grid[0])
    split = None
    orientation = None
    # Find a full-width/full-height separator whose removal leaves equal panels.
    for r in range(1, h - 1):
        if len(set(grid[r])) == 1 and r == h - r - 1:
            split, orientation = r, "h"
            break
    if split is None:
        for c in range(1, w - 1):
            if all(row[c] == grid[0][c] for row in grid) and c == w - c - 1:
                split, orientation = c, "v"
                break
    if orientation == "h":
        a, b = grid[:split], grid[split + 1:]
    elif orientation == "v":
        a = [row[:split] for row in grid]
        b = [row[split + 1:] for row in grid]
    else:
        return grid

    # A lone marker in an otherwise empty panel selects a solid fill color.
    for panel, other in ((a, b), (b, a)):
        flat = [v for row in panel for v in row]
        nonzero = [v for v in flat if v != 0]
        if len(nonzero) == 1:
            marker = nonzero[0]
            return [[marker for _ in row] for row in other]

    # Otherwise the common color is the overlap; encode overlap as 3,
    # and all other positions as the shared panel background 9.
    common = set(v for row in a for v in row) & set(v for row in b for v in row)
    common.discard(0)
    if not common:
        return grid
    shared = min(common)
    return [[3 if a[i][j] == shared and b[i][j] == shared else 9
             for j in range(len(a[0]))] for i in range(len(a))]
"
}

